        symbol("AlbumsFilled", fill = PathFillType.EvenOdd, path = "M220-140q-33 0-56.5-23.5T140-220v-520q0-33 23.5-56.5T220-820h90v680h-90Zm150 0v-680h370q33 0 56.5 23.5T820-740v520q0 33-23.5 56.5T740-140H370Zm80-480h230v-60H450v60Z")
    }
}

private fun symbol(name: String, path: String, fill: PathFillType = PathFillType.NonZero): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f)
        .addGroup(translationY = 960f) // Material Symbols use a 0 -960 960 960 view box
        .addPath(PathParser().parsePathString(path).toNodes(), fill = SolidColor(Color.Black), pathFillType = fill)
        .clearGroup()
        .build()
